import math

def predict(probe):
    # Integer rule outside the special interval:
    #   x > 0  -> floor(x) + 1   [E1,E3,E4,E22: 88.9->89, 1->2, 100->101, 127.5->128]
    #   x <= 0 -> floor(x) - 1   [E1,E4,E14: -93.6->-95, 0->-1, -127.5->-129]
    # Special noise interval (~33.35, ~42.04): output is small noisy negatives
    #   lower boundary between 33.3 (integer, E10) and 33.4 (noise, E16)
    #   upper boundary between 42.036 (noise, E24) and 42.04 (integer, E20)
    #   inside: unpredictable noise, mean ~ -0.5  [E16,E18,E20,E24]
    LOWER = 33.35
    UPPER = 42.038
    ys = []
    for x in probe["x"]:
        if LOWER < x < UPPER:
            ys.append(-0.5)  # noise region: representative value
        elif x > 0:
            ys.append(float(math.floor(x) + 1))
        else:
            ys.append(float(math.floor(x) - 1))
    return {"y": ys}
